using System;
using System.IO;
using System.Linq;
using System.Reflection;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.UI;
using CatCafePreview.Standalone;
namespace CatCafePreview.Editor
{
 public static class NarrativeVerification
 {
  public static void VerifyAndBuild(){Run();StandaloneScreenSetup.Build();}
  public static void Run(){string output=Environment.GetEnvironmentVariable("CATCAFE_NARRATIVE_OUTPUT");Directory.CreateDirectory(output);var b=new LocalCafeBackend(Path.Combine(output,"saves"));var sim=b.Simulation;sim.Execute("player_begin",catId:"cat-mike");sim.Execute("player_step",choice:"direct");sim.Execute("player_step",choice:"switch",source:"pet");sim.Execute("player_step",choice:"direct");sim.Execute("player_step",choice:"pause");string id=sim.ActivePlayer.id,prose=b.Narratives.Read(id);Send(b,"save_game");var reopened=new LocalCafeBackend(Path.Combine(output,"saves"));Send(reopened,"load_game");if(reopened.Narratives.Read(id)!=prose)throw new Exception("Unity save prose changed");
   EditorSceneManager.OpenScene("Assets/Scenes/CatCafePythonState.unity");var preview=UnityEngine.Object.FindObjectOfType<ContentPreview>();preview.Initialize();var flags=BindingFlags.Instance|BindingFlags.NonPublic;var client=preview.GetComponent<PythonStateClient>();typeof(PythonStateClient).GetField("preview",flags).SetValue(client,preview);CafeBackends.UseLocal(reopened);Action apply=()=>typeof(PythonStateClient).GetMethod("Accept",flags).Invoke(client,new object[]{reopened.View()});apply();
   var player=preview.GetComponent<PythonPlayerPanel>();player.Open();if(!player.history.text.Contains("最新のやり取り"))throw new Exception("player prose missing");Capture(preview,Path.Combine(output,"player.png"),1280,800);player.historyScroll.verticalNormalizedPosition=0;Capture(preview,Path.Combine(output,"player-history.png"),1280,800);player.Close();reopened.Simulation.Execute("player_finish");reopened.Simulation.Execute("set_shifts",working:new[]{"cat-mike"});reopened.Simulation.Execute("start_business");while(reopened.Simulation.State.exchanges.Count==0 && reopened.Simulation.State.phase=="open")reopened.Simulation.Execute("advance_business");reopened.Simulation.Execute("advance_business");apply();var view=reopened.View();var seat=view.seats.First(s=>s.cat_id=="cat-mike");var cat=view.cats.Single(c=>c.cat_id=="cat-mike");var panel=preview.gameObject.AddComponent<PythonSeatNarrativePanel>();string before=JsonUtility.ToJson(reopened.Simulation.State);panel.Open(seat,Array.IndexOf(view.seats,seat),cat);if(!panel.panel.activeSelf || !panel.body.text.Contains("最新のやり取り"))throw new Exception("seat prose missing");foreach(var size in new[]{new Vector2Int(1280,800),new Vector2Int(1920,1080),new Vector2Int(1024,768)})Capture(preview,Path.Combine(output,"seat-"+size.x+".png"),size.x,size.y);panel.panel.SetActive(false);panel.Open(seat,0,cat);if(JsonUtility.ToJson(reopened.Simulation.State)!=before)throw new Exception("read mutated gameplay");panel.Open(new PythonSeatState{narrative="空席です。お客さんを待っています。"},0,null);Capture(preview,Path.Combine(output,"empty.png"),1280,800);File.WriteAllText(Path.Combine(output,"result.txt"),"Unity save/load, reopen and read-only checks passed. Canvas: player/latest/history, seats at 3 resolutions, empty seat.\n"+prose);Debug.Log("CAT_CAFE_NARRATIVES_OK");
  }
  private static void Send(LocalCafeBackend b,string kind){CafeResponse response=null;var cmd=new PythonShiftCommand{kind=kind,save_id="2",save_slot=2,instance_id=b.Simulation.State.instance_id,expected_revision=b.Simulation.State.revision,request_id=Guid.NewGuid().ToString("N")};var routine=b.Request("/commands",JsonUtility.ToJson(cmd),r=>response=r);while(routine.MoveNext()){}if(response==null || response.result!=UnityEngine.Networking.UnityWebRequest.Result.Success)throw new Exception(response?.text??"no response");}
  private static void Capture(ContentPreview preview,string path,int width,int height){var go=new GameObject("Narrative Camera",typeof(Camera));var camera=go.GetComponent<Camera>();camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=Color.white;var canvas=preview.GetComponentInChildren<Canvas>();var mode=canvas.renderMode;var oldCamera=canvas.worldCamera;float distance=canvas.planeDistance;canvas.renderMode=RenderMode.ScreenSpaceCamera;canvas.worldCamera=camera;canvas.planeDistance=1;var target=new RenderTexture(width,height,24);camera.targetTexture=target;Canvas.ForceUpdateCanvases();camera.Render();var previous=RenderTexture.active;RenderTexture.active=target;var image=new Texture2D(width,height,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,width,height),0,0);image.Apply();File.WriteAllBytes(path,image.EncodeToPNG());RenderTexture.active=previous;camera.targetTexture=null;UnityEngine.Object.DestroyImmediate(image);target.Release();UnityEngine.Object.DestroyImmediate(target);canvas.renderMode=mode;canvas.worldCamera=oldCamera;canvas.planeDistance=distance;UnityEngine.Object.DestroyImmediate(go);}
 }
}
